export const COUNTRIES: CountryOption[] = COUNTRY_TUPLES.map(([code, name, phoneCode]) => ({
  code,
  name,
  phoneCode,
}));

const COUNTRY_BY_CODE = new Map(COUNTRIES.map((c) => [c.code, c]));

export const DEFAULT_COUNTRY_CODE = 'US';

/** Countries whose phone numbers use the North American 10-digit mask. */
export const NANP_COUNTRY_CODES = new Set(['US', 'CA']);

export function getCountry(code: string | null | undefined): CountryOption | undefined {
  return code ? COUNTRY_BY_CODE.get(code) : undefined;
}

export function getCountryName(code: string | null | undefined): string {
  return getCountry(code)?.name ?? (code ?? '');
}

/** Subdivisions for a country, alphabetical. Empty when the dataset has none. */
export function getRegions(countryCode: string | null | undefined): RegionOption[] {
  if (!countryCode) return [];
  const tuples = REGION_TUPLES[countryCode];
  if (!tuples) return [];
  return tuples.map(([code, name]) => ({ code, name }));
}

export function hasRegions(countryCode: string | null | undefined): boolean {
  return getRegions(countryCode).length > 0;
}

/** Country-appropriate label for the subdivision field. */
export function getRegionLabel(countryCode: string | null | undefined): string {
  if (countryCode === 'US') return 'State';
  if (countryCode === 'CA') return 'Province';
  if (!hasRegions(countryCode)) return 'Region / Province';
  return 'State / Province';
}

/** Resolves a stored region value (code or name) to its display name. */
export function getRegionName(countryCode: string | null | undefined, regionValue: string | null | undefined): string {
  if (!regionValue) return '';
  const match = getRegions(countryCode).find((r) => r.code === regionValue);
  return match?.name ?? regionValue;
}
